/* Local Socket.IO v4-compatible client subset for the CRM chat namespace.
 * Implements Engine.IO v4 WebSocket, namespaces, acknowledgements and reconnects.
 * Kept in-repository so chat interaction never depends on a third-party CDN. */
(function(global){"use strict";
  function Events(){this.handlers={};}
  Events.prototype.on=function(name,fn){(this.handlers[name]||(this.handlers[name]=[])).push(fn);return this;};
  Events.prototype.fire=function(name){var args=[].slice.call(arguments,1);(this.handlers[name]||[]).slice().forEach(function(fn){try{fn.apply(null,args);}catch(error){setTimeout(function(){throw error;});}});};
  function Socket(namespace,options){
    Events.call(this);this.namespace=namespace||"/";this.options=options||{};this.connected=false;this.ws=null;this.acks={};this.nextAck=1;this.attempt=0;this.closed=false;this.io=new Events();this.connect();
  }
  Socket.prototype=Object.create(Events.prototype);
  Socket.prototype.connect=function(){
    var self=this, protocol=location.protocol==="https:"?"wss:":"ws:";
    try{self.ws=new WebSocket(protocol+"//"+location.host+"/socket.io/?EIO=4&transport=websocket");}
    catch(error){self.failure(error);return self;}
    self.ws.onopen=function(){};
    self.ws.onmessage=function(event){self.packet(String(event.data));};
    self.ws.onerror=function(){self.fire("error",new Error("Connexion WebSocket impossible"));};
    self.ws.onclose=function(){var was=self.connected;self.connected=false;if(was)self.fire("disconnect","transport close");if(!self.closed)self.retry();};
    return self;
  };
  Socket.prototype.packet=function(packet){
    var self=this;
    if(packet.charAt(0)==="0"){
      self.ws.send("40"+self.namespace+","+JSON.stringify(self.options.auth||{}));return;
    }
    if(packet==="2"){self.ws.send("3");return;}
    if(packet.indexOf("40"+self.namespace)===0){
      self.connected=true;self.attempt=0;self.fire("connect");return;
    }
    if(packet.indexOf("44"+self.namespace)===0){self.failure(new Error("Namespace refusé"));return;}
    if(packet.indexOf("42"+self.namespace+",")===0){
      var text=packet.slice(("42"+self.namespace+",").length),match=text.match(/^(\d+)(\[.*)$/),ackId=null;
      if(match){ackId=Number(match[1]);text=match[2];}
      try{var data=JSON.parse(text),args=data.slice(1);if(ackId!==null)args.push(function(value){self.ws.send("43"+self.namespace+","+ackId+JSON.stringify([value]));});self.fire.apply(self,[data[0]].concat(args));}catch(error){self.fire("error",error);}return;
    }
    if(packet.indexOf("43"+self.namespace+",")===0){
      var rest=packet.slice(("43"+self.namespace+",").length),found=rest.match(/^(\d+)(\[.*)$/);if(!found)return;
      var pending=self.acks[Number(found[1])];if(pending){delete self.acks[Number(found[1])];clearTimeout(pending.timer);var values=JSON.parse(found[2]);pending.callback.apply(null,[null].concat(values));}
    }
  };
  Socket.prototype.failure=function(error){this.fire("connect_error",error);this.fire("error",error);if(this.ws)this.ws.close();else this.retry();};
  Socket.prototype.retry=function(){var self=this,delay=Math.min(10000,1000*Math.pow(2,self.attempt++));self.io.fire("reconnect_attempt",self.attempt);setTimeout(function(){if(!self.closed){self.connect();if(self.attempt>1)self.io.fire("reconnect",self.attempt);}},delay);};
  Socket.prototype.emit=function(name,payload,callback){
    if(!this.connected)return this;
    var ack="";
    if(typeof callback==="function"){var id=this.nextAck++;ack=String(id);this.acks[id]={callback:callback,timer:null};}
    this.ws.send("42"+this.namespace+","+ack+JSON.stringify([name,payload]));return this;
  };
  Socket.prototype.timeout=function(milliseconds){
    var self=this;return {emit:function(name,payload,callback){
      if(!self.connected){callback(new Error("Temps réel déconnecté"));return;}
      var id=self.nextAck++;self.acks[id]={callback:callback,timer:setTimeout(function(){if(self.acks[id]){delete self.acks[id];callback(new Error("Délai de réponse dépassé"));}},milliseconds)};
      self.ws.send("42"+self.namespace+","+id+JSON.stringify([name,payload]));
    }};
  };
  Socket.prototype.disconnect=function(){this.closed=true;if(this.ws)this.ws.close();};
  global.io=function(namespace,options){return new Socket(namespace,options);};
  global.io.version="4.8-compatible-local";
})(window);
